import numpy as np
import matplotlib.pyplot as plt

# Load simulation data generated by the C++ simulator.
data = np.genfromtxt('output/simulation.csv', delimiter=',', names=True)

x = data['x']
y = data['y']
z = data['z']

qw = data['qw']
qx = data['qx']
qy = data['qy']
qz = data['qz']

# Rotate the body +z axis into the world frame using each logged quaternion.
# For q = (w, x, y, z), the third column of the rotation matrix gives
# the world-frame direction of the vehicle's body +z axis.
body_z_x = 2.0 * (qx * qz + qw * qy)
body_z_y = 2.0 * (qy * qz - qw * qx)
body_z_z = 1.0 - 2.0 * (qx * qx + qy * qy)

fig = plt.figure()
ax = fig.add_subplot(111, projection='3d')

# Plot the flight path.
ax.plot(x, y, z, label='Trajectory')
ax.scatter(x[0], y[0], z[0], s=30, label='Start')
ax.scatter(x[-1], y[-1], z[-1], s=30, label='End')

# Draw simple rocket-shaped orientation markers at selected points.
num_markers = min(6, len(x))
marker_indices = np.linspace(0, len(x) - 1, num_markers, dtype=int)
rocket_length = 3.0

for i in marker_indices:
    direction = np.array([
        body_z_x[i],
        body_z_y[i],
        body_z_z[i]
    ])
    direction = direction / np.linalg.norm(direction)

    center = np.array([x[i], y[i], z[i]])
    tail = center - 0.5 * rocket_length * direction
    nose = center + 0.5 * rocket_length * direction

    # Vehicle centerline.
    ax.plot(
        [tail[0], nose[0]],
        [tail[1], nose[1]],
        [tail[2], nose[2]],
        linewidth=3,
    )

    # Nose marker makes the forward direction clear.
    ax.scatter(nose[0], nose[1], nose[2], s=20)

ax.set_xlabel('X (m)')
ax.set_ylabel('Y (m)')
ax.set_zlabel('Z (m)')
ax.set_title('3D Trajectory with Vehicle Orientation')
ax.legend()

plt.show()